//==============================================================================
// The maker's mark, parsed once per process. Returns nullptr only if the SVG fails to parse, which
// would be a build-time mistake, not a runtime condition.
inline juce::Drawable* catMark()
{
    static const std::unique_ptr<juce::Drawable> cat { juce::Drawable::createFromImageData (
        assets::catSvg, std::strlen (assets::catSvg)) };
    return cat.get();
}

// Draw the mark centred in `area`, keeping its aspect. `scale` trims it inside the box the way the
// family's lockups do (the cat's whiskers want a little air).
inline void drawCat (juce::Graphics& g, juce::Rectangle<float> area, float scale = 1.0f)
{
    if (auto* cat = catMark())
        cat->drawWithin (g, area, juce::RectanglePlacement::centred, scale);
}

// The wordmark face, decoded once per process. Null only if the embedded data is corrupt.
inline juce::Typeface::Ptr wordmarkTypeface()
{
    static const juce::Typeface::Ptr face = []
    {
        juce::MemoryOutputStream b64;
        for (const char* const* c = assets::wordmarkBase64; *c != nullptr; ++c)
            b64 << *c;

        juce::MemoryOutputStream ttf;
        if (! juce::Base64::convertFromBase64 (ttf, b64.toString()))
            return juce::Typeface::Ptr {};

        return juce::Typeface::createSystemTypefaceFor (ttf.getData(), ttf.getDataSize());
    }();
    return face;
}

// The wordmark face at a size, with the system's bold as the last resort (a decode that failed must
// still leave the product with readable words).
inline juce::Font wordmarkFont (float height)
{
    if (auto tf = wordmarkTypeface())
        return juce::Font (juce::FontOptions().withHeight (height).withTypeface (tf));
    return juce::Font (juce::FontOptions (height, juce::Font::bold));
}

